o."},"frame":3}],"keyCues":[{"es":"La fuerza sale de la cadera, no de los brazos."},{"es":"Arriba: de pie, recto, glúteos apretados."}],"commonMistakes":[{"es":"Hacer sentadilla en vez de bisagra."},{"es":"Subir la pesa con los hombros."}],"breathing":null}'::jsonb, '{"grip":"two_hand_handle","startPosition":{"es":"Pesa en el suelo frente a ti, como en la posición de partida del swing."},"hipHinge":{"cues":[{"es":"Empuja la cadera hacia atrás como si cerraras una puerta con los glúteos."},{"es":"Columna neutra: mirada al suelo 2 m delante, pecho abierto."}],"drillExerciseId":"kb_deadlift"},"lumbarSafety":[{"es":"Activa el core (bracing) antes de cada repetición."},{"es":"Cada repetición empieza con la espalda neutra: si se curva, para y reinicia."}],"suggestedWeightKg":{"beginner":12,"intermediate":16,"advanced":24},"prerequisites":["kb_deadlift"]}'::jsonb, '[{"flag":"ballistic","note":{"es":"Alternativa: peso muerto con kettlebell, lento y controlado."}}]'::jsonb, '{stretch_hamstring_supine,stretch_hip_flexor_kneeling}', '{potencia}') on conflict (id) do update set version = excluded.version, name = excluded.name, description = excluded.description, block_types = excluded.block_types, muscle_groups = excluded.muscle_groups, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, laterality = excluded.laterality, complexity_level = excluded.complexity_level, impact_level = excluded.impact_level, restriction_flags = excluded.restriction_flags, equipment_required = excluded.equipment_required, equipment_optional = excluded.equipment_optional, anatomy = excluded.anatomy, prescription = excluded.prescription, progression_chain_id = excluded.progression_chain_id, progression_step = excluded.progression_step, progression = excluded.progression, media = excluded.media, instructions = excluded.instructions, kettlebell_guide = excluded.kettlebell_guide, safety_notes = excluded.safety_notes, cooldown_stretch_ids = excluded.cooldown_stretch_ids, tags = ex