,"frame":3}],"keyCues":[{"es":"La pesa rodea la mano: no la dejes caer sobre el antebrazo."},{"es":"Arriba: bíceps junto a la oreja."}],"commonMistakes":[{"es":"Golpear el antebrazo."},{"es":"Tirar con el brazo en vez de con la cadera."}],"breathing":null}'::jsonb, '{"grip":"one_hand_handle","startPosition":{"es":"Igual que el swing a una mano; domina el clean antes de aprenderlo."},"hipHinge":{"cues":[{"es":"Empuja la cadera hacia atrás como si cerraras una puerta con los glúteos."},{"es":"Columna neutra: mirada al suelo 2 m delante, pecho abierto."}],"drillExerciseId":"kb_high_pull"},"lumbarSafety":[{"es":"Activa el core (bracing) antes de cada repetición."},{"es":"Costillas abajo y glúteos apretados: si arqueas la espalda, baja el peso."}],"suggestedWeightKg":{"beginner":8,"intermediate":12,"advanced":16},"prerequisites":["kb_clean","kb_swing_1h"]}'::jsonb, '[{"flag":"overhead","note":{"es":"Alternativa sin brazos arriba: clean con kettlebell."}},{"flag":"ballistic","note":{"es":"Alternativa: peso muerto a una pierna."}}]'::jsonb, '{stretch_hamstring_supine,stretch_cross_body_shoulder}', '{potencia}') on conflict (id) do update set version = excluded.version, name = excluded.name, description = excluded.description, block_types = excluded.block_types, muscle_groups = excluded.muscle_groups, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, laterality = excluded.laterality, complexity_level = excluded.complexity_level, impact_level = excluded.impact_level, restriction_flags = excluded.restriction_flags, equipment_required = excluded.equipment_required, equipment_optional = excluded.equipment_optional, anatomy = excluded.anatomy, prescription = excluded.prescription, progression_chain_id = excluded.progression_chain_id, progression_step = excluded.progression_step, progression = excluded.progression, media = excluded.media, instructions = excluded.instructions, kettlebell_guide = excluded.kettlebell_guide, safety_notes = excluded.safety_