ir."}],"commonMistakes":[{"es":"Empujar con el brazo antes de usar las piernas."}],"breathing":null}'::jsonb, '{"grip":"rack","startPosition":{"es":"Lleva la pesa a rack con un clean."},"hipHinge":null,"lumbarSafety":[{"es":"Activa el core (bracing) antes de cada repetición."},{"es":"Costillas abajo y glúteos apretados: si arqueas la espalda, baja el peso."}],"suggestedWeightKg":{"beginner":8,"intermediate":12,"advanced":20},"prerequisites":["kb_push_press"]}'::jsonb, '[{"flag":"overhead","note":{"es":"Alternativa: press de suelo con kettlebell."}}]'::jsonb, '{stretch_cross_body_shoulder,stretch_triceps_overhead}', '{potencia}') on conflict (id) do update set version = excluded.version, name = excluded.name, description = excluded.description, block_types = excluded.block_types, muscle_groups = excluded.muscle_groups, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, laterality = excluded.laterality, complexity_level = excluded.complexity_level, impact_level = excluded.impact_level, restriction_flags = excluded.restriction_flags, equipment_required = excluded.equipment_required, equipment_optional = excluded.equipment_optional, anatomy = excluded.anatomy, prescription = excluded.prescription, progression_chain_id = excluded.progression_chain_id, progression_step = excluded.progression_step, progression = excluded.progression, media = excluded.media, instructions = excluded.instructions, kettlebell_guide = excluded.kettlebell_guide, safety_notes = excluded.safety_notes, cooldown_stretch_ids = excluded.cooldown_stretch_ids, tags = excluded.tags, updated_at = now();
